<script setup lang="ts">
import type {ApiClient} from '@kuaixie/sdk';
import {useBusinessAuth} from './useBusinessAuth';
const props=defineProps<{client:ApiClient}>();const emit=defineEmits<{accepted:[];legal:[type:string];support:[]}>();
const p=useBusinessAuth(props.client,{persistLocale:value=>localStorage.setItem('kx.locale',value),sessionAccepted:()=>emit('accepted'),openLegal:type=>emit('legal',type),openSupport:()=>emit('support')});
</script>
<template><section class="business-card"><h2>{{$t(p.mode.value==='signin'?'v15.login':p.mode.value==='signup'?'v15.signup':'v15.resetTitle')}}</h2>
 <form @submit.prevent="p.submit"><label>{{$t('account.title')}}<select v-model="p.channel.value"><option value="phone">{{$t('v15.phone')}}</option><option value="email">{{$t('v15.email')}}</option></select></label><select v-if="p.channel.value==='phone'" :value="p.countryCode.value" @change="p.chooseCountry(($event.target as HTMLSelectElement).value)"><option v-for="country in p.countryCodes" :key="country">{{country}}</option></select><label>{{$t('v15.account')}}<input v-model="p.contact.value" autocomplete="username" required/></label>
 <label v-if="p.needPassword.value">{{$t('v15.password')}}<input v-model="p.password.value" type="password" maxlength="20" :autocomplete="p.mode.value==='signin'?'current-password':'new-password'" required/></label>
 <template v-if="p.needCode.value"><button type="button" @click="p.refreshCaptcha(true)"><img v-if="p.captchaImage.value" :src="p.captchaImage.value" :alt="$t('v15.captcha')"/></button><input v-model="p.captchaText.value" maxlength="4" :aria-label="$t('v15.captcha')"/><label>{{$t('v15.code')}}<input v-model="p.code.value" maxlength="6" autocomplete="one-time-code"/></label><button type="button" :disabled="p.busy.value||p.codeWait.value>0" @click="p.sendCode">{{p.codeWait.value||$t('v15.sendCode')}}</button></template>
 <template v-if="p.mode.value==='signup'"><label>{{$t('v15.role')}}<select v-model="p.role.value"><option value="buyer">{{$t('account.buyer')}}</option><option value="carrier">{{$t('account.carrier')}}</option><option value="enterprise">{{$t('v15.enterprise')}}</option></select></label><input v-model="p.inviteCode.value" :placeholder="$t('v15.inviteCode')"/><template v-if="p.role.value==='enterprise'"><input v-model="p.enterpriseName.value" :placeholder="$t('v15.enterpriseName')"/><input v-model="p.businessLicenseNo.value" maxlength="18" :placeholder="$t('v15.businessLicenseNo')"/></template></template>
 <label><input v-model="p.agreed.value" type="checkbox"/>{{$t('v15.mustAgree')}}</label><div class="business-tabs"><button type="button" @click="emit('legal','agreement')">{{$t('v15.agreement')}}</button><button type="button" @click="emit('legal','privacy')">{{$t('v15.privacy')}}</button></div><button :disabled="p.busy.value">{{$t(p.mode.value==='recover'?'v15.resetTitle':p.mode.value==='signup'?'v15.signup':'v15.login')}}</button></form>
 <nav class="business-tabs"><button @click="p.changeMode">{{$t(p.mode.value==='signin'?'v15.signup':'v15.login')}}</button><button v-if="p.mode.value==='signin'" @click="p.withCode.value=!p.withCode.value">{{$t(p.withCode.value?'v15.password':'v15.code')}}</button><button @click="p.openRecover">{{$t('v15.resetTitle')}}</button><button @click="p.askSupport">{{$t('portal.chat.title')}}</button></nav><p v-if="p.error.value" role="alert">{{p.error.value}}</p><p v-if="p.notice.value" role="status">{{p.notice.value}}</p></section></template>
